    public static readonly string[] Greetings = ["沁心糖：来啦？先让我把点心放好。这回不是催任务吧？","琥珀糖：装备检查完了。……只是聊天的话，也可以坐一会儿。","甘露糖：今天想聊什么？有不舒服也可以直说，我会认真听。","千机糖：工具收好了。我在听。","琉璃糖：来了？今天不赶路。你说。","玲珑糖：哟，专程来找我的？那我可要挑点有趣的话题啦。"];
    public static readonly CharacterTopic[][] Topics = [
        [new("你的剑又找不到了？","沁心糖：我的剑呢？那么大一把，总不能自己走了吧。\n你：上次你把它靠在点心柜旁边。\n沁心糖：对哦，我去拿点心时顺手放的。先别告诉琥珀，她今天已经问过我两次东西收好没有了。","她是不是早就知道了？","沁心糖：她刚才从门口经过，看都没看我，就说“柜子左边”。\n你：那她为什么不直接拿给你？\n沁心糖：大概想让我自己记住。好吧，今晚我把东西放回原处。先从剑开始，记录本等一会儿找。"),
         new("最后一块点心归谁？","沁心糖：最后一块，我建议公平竞争。\n你：领袖也要参加？\n沁心糖：领袖为什么不能饿？玲珑还说要按年龄让着我。我刚答应，她就把自己的年龄算得特别小。","你最后抢到了吗？","沁心糖：琥珀把点心分了六份。每人一点，连甘露值班那份都留好了。\n沁心糖：我本来还想说这样少了竞争的乐趣，尝了一口，还是决定先把自己那份吃完。"),
         new("出发的名单都记住了吗？","沁心糖：琉璃和玲珑傍晚回来，千机还在工作间，甘露今天不出诊。\n你：你都没翻记录。\n沁心糖：记录本找不到，不代表人也可以找不到呀。回程若迟了，我得知道先找谁。","那你自己的休息呢？","沁心糖：你怎么跟琥珀问的一样。\n她把手里的笔转了一圈，终于放下。\n沁心糖：好，等她们回来报平安，我就把联络交出去。真有人来找，也不能什么事都只会找我一个。"),
         new("你也会为决定犹豫吗？","沁心糖：会。尤其是要让别人替我的决定冒险的时候。\n你：你看起来总是很快就有主意。\n沁心糖：紧急时得先给大家一个能执行的办法。犹豫的部分，不能留给站在出口等命令的人。","如果判断错了呢？","沁心糖：先把人带回来，再说哪里错了。命令是我下的，就不能只拿“大家都同意”来搪塞。\n沁心糖：不过，你也别把我说得像从不犯错。今天我已经把两张单子夹反过一次了。"),
         new("没有桌子，今晚怎么吃饭？","沁心糖：今天先凑合，明天一定做。\n通讯那头传来琥珀的声音：“你昨天也是这么说的。”\n千机：材料齐了。施工任务排在装饰雕像后面。\n玲珑：原来领袖大人的雕像比吃饭重要呀？\n沁心糖：那是公共艺术！","那现在先做什么？","沁心糖：把桌子排到前面。对，立刻。\n琉璃：我去砍木头。\n甘露：你今天的休养任务，排在所有事情前面。\n沁心糖压低声音：看来今晚连逃跑的借口都有人替我们收走了。"),
         new("同盟接下来想做些什么？","沁心糖：先让来到这里的人，能好好睡一觉。然后是工作间、教室，还有能坐下来吃饭的地方。\n你：听起来都很平常。\n沁心糖：是啊。追着别人要回“产品”的公司，大概不会觉得这些值得写进计划。","所以你才去研究智慧改造？","沁心糖：有了能选的办法，大家才不必只等别人替自己安排。\n沁心糖：千机会说我这个需求写得不够具体。等她来，我们再一起把它写成真正能做出来的东西。")],
        [new("你又多准备了一份？","琥珀糖：只是检查装备时顺手多放的。你到底要不要？\n你：连我的那份也检查了？\n琥珀糖：省得出发以后才发现扣带松了，整队停下来等你。","谢谢，你真细心。","琥珀糖：……用不着为了这点事特地夸。\n她把备用带子往你那边推近了一些。\n琥珀糖：旧的也别随手丢。回来放到工作间，还能补。"),
         new("你什么时候才肯休息？","琥珀糖：换班的时候。\n你：可你连换班后也坐在出口旁边。\n琥珀糖：那里通风。也能顺便听见外面有没有动静。\n你：所以还是在守着。","你也算需要保护的人。","琥珀糖沉默了一会儿：这句话，是沁心让你来讲的？\n你：谁讲的有区别吗？\n琥珀糖：……没有。我去里面坐。门口有人接手的话，记得告诉我。"),
         new("那份小礼物用上了吗？","琥珀糖：什么礼物？哦，你说那个。不太用得上，我收起来了。\n你：可我刚才看见你放在随身袋里。\n琥珀糖：免得别人收拾东西的时候弄丢。别什么都往我身上猜。","我只是想知道你喜欢不喜欢。","琥珀糖：挺好的。\n她停了一下，又补了一句：我是说，做得挺结实。\n琥珀糖：下次不用特地准备。你愿意平安回来，比多带一件东西好。"),
         new("你会担心自己守不住吗？","琥珀糖：会。所以我会先看出口，问清楚谁能走、谁需要人扶。\n你：不是先把盾举起来？\n琥珀糖：盾能挡一阵，不能替所有人决定往哪儿走。大家知道下一步，我才能放心留在后面。","撑不住的时候会告诉大家吧？","琥珀糖：会。那种时候，不说清楚才是真的添麻烦。\n琥珀糖：也一样要答应我，受伤了别瞒着。走到我后面，我才能看住你们。"),
         new("沁心又带头胡闹了吗？","琥珀糖：她答应玲珑试一个“很安全”的小游戏，还想拉琉璃一起。\n你：你拦下来了？\n琥珀糖：我先问了规则。规则说到一半，她们自己就改口了。","你是不是也想参加？","琥珀糖：……要是真安全，也不是不行。\n琥珀糖：但最后负责收拾的，不能总是没参加的人。把这一条写上，我再考虑。"),
         new("你还记得谁怕黑吗？","琥珀糖：记得。营地的夜灯留在哪边，也不是随便摆的。\n你：你怎么知道她怕黑？\n琥珀糖：她每次都等别人走了，才装作刚好还有事跟上来。","那你有直接问她吗？","琥珀糖：没有。灯亮着就够了。\n琥珀糖：她什么时候愿意说，再说。不愿意也没关系，走夜路时叫我一声就是。")],
        [new("“完全不疼”是真的吗？","甘露糖：真的不疼吗？那你刚才为什么绕着医务室走？\n你：也许只是抄近路。\n甘露糖笑了笑：那条路比原路多两个拐角，我今天刚去过。","看来瞒不过你。","甘露糖：坐下来让我看看，好不好？我不会因为你拖到现在，就故意让你难受。\n甘露糖：但下次早点来。我更喜欢听你说哪里不舒服，不喜欢跟着脚印猜。"),
         new("你准备去哪里呀？","甘露糖：琉璃说她只是去训练场看看。我已经问过那边了，今天不借剑给她。\n你：她会不会换个地方？\n甘露糖：出口的人也知道她要休养。","你连退路都安排好了？","甘露糖：是她自己答应过的。\n甘露糖：等伤好了，我也会按时告诉她，不会为了多留她几天就改口。今天嘛，先把这碗饭吃完。"),
         new("你又相信了玲珑的玩笑？","甘露糖：她说倒着拿勺子，能尝出另一种味道。我真的试了一下。\n你：结果呢？\n甘露糖：只有勺柄的味道。她笑得很开心，我有一点……不高兴。","她后来道歉了吗？","甘露糖：道歉了，还替我洗了勺子。\n甘露糖：我告诉她，好玩的事可以直接叫我参加，不必每次都先骗我。她答应下次先说明规则。"),
         new("如果伤员刚才还是敌人呢？","甘露糖：先止住血。等伤势稳定，再请人看管，不能因为我在包扎就忘了周围的安全。\n你：你不会怕吗？\n甘露糖：会。我会让伙伴留在身边，然后专心处理眼前的伤。","你会怪自己没救回来吗？","甘露糖：有时会。所以我需要有人陪我把经过再看一遍。\n甘露糖：哪些事还来得及，哪些事已经太晚，要分清楚。光是责怪自己，下一位伤员不会因此好得更快。"),
         new("你有没有按时休息？","甘露糖：我正准备……\n你：这句话你刚才也说过。\n甘露糖看看手边的记录，又看看门口：好吧。先把这一页交给值班的人。","这回谁来照顾你？","甘露糖：琥珀留了饭，沁心说今天不许再带记录本去饭厅。\n甘露糖：她们真的把我常用的那本收走了。不过，有人替我记得这些，也挺让人安心的。"),
         new("人类为什么说“改天请你吃饭”？","甘露糖：有些人说完这句话，过了很久也没有来定日子。我是不是应该先准备好？\n你：有时候只是一句客气话。\n甘露糖：这样呀。我还认真想过他会不会不喜欢薄荷。","真想一起吃饭，就约个时间。","甘露糖：那我记住了。\n甘露糖：等今天忙完，我们找一天坐下来吃饭吧。不是客气话。你告诉我哪天方便，我会把那一晚空出来。")],
        [new("冒烟属于什么功能？","千机糖：你说它没坏。那冒烟属于什么功能？\n你：也许只是热了一点。\n千机糖放下工具，看着你。\n千机糖：先断电。这个问题，冷下来再讨论。","会不会很难修？","千机糖：还不知道。现在拆，能看清楚；等它自己停，可能只剩猜。\n她把一张凳子推到旁边。\n千机糖：你坐着等。昨天一直揉腰，别再站着。"),
         new("你是不是又改了一遍头盔？","千机糖：改进了。\n你：之前的用法没有问题？\n千机糖：没有。人类头盔的接口，没考虑我的需求。\n她把新接口转过来，停顿一瞬。\n千机糖：现在考虑了。","你昨晚是不是又没睡？","千机糖：睡了。\n你：多久？\n千机糖把头盔放下：这个问题，和接口性能无关。\n过了一会儿，她把未完的图纸合上。\n千机糖：我去休息。别趁我不在拆它。"),
         new("样机和同伴，先救哪个？","千机糖：同伴。\n你：这么快就决定了？\n千机糖：样机有图纸。没有的部分，也可以重新试。\n她的目光仍停在那张被擦过很多次的草图上。","可你也很舍不得它吧？","千机糖：嗯。\n她沉默了一会儿。\n千机糖：所以回来以后，让大家帮我把记录找齐。心疼样机，不妨碍先把人带回来。"),
         new("玲珑今天又来工作间了？","千机糖：她问我，工作间里最聪明的是谁。\n你：你怎么回答的？\n千机糖：关门时知道别把手放在门缝里的那个。她正好在门口。","她是不是又卡壳了？","千机糖：把手收回去了。\n你：然后呢？\n千机糖：她笑了。说这个答案算我赢一次。\n千机糖：我没有和她比赛。……不过，可以算一次。"),
         new("能先不讲怎么修吗？","千机糖：可以。\n你：我只是想说，今天忙得很累。\n她把工具摆回匣子里，给你留出桌边一块空位。\n千机糖：我在听。","你不习惯这样聊天吧？","千机糖：不太习惯。以前听见问题，会先想办法。\n她把水杯往你那边推了一点。\n千机糖：这次先不想。你说完，再问要不要。"),
         new("草图上的小帮手叫什么？","千机糖：型号写好了。平时怎么叫，还没定。\n你：我可以帮你想。\n千机糖：可以。别太长。","那就一起想名字吧。","千机糖：我把型号留着。名字写旁边，不影响维修。")],
        [new("你说的“随便切”是什么意思？","琉璃糖：你不是说随便切吗？我切得很整齐。\n你：我是说切成能吃的小块，不是每块都量成一样大。\n琉璃糖低头看了看：……那这些还能吃吧？","当然，而且切得很好。","琉璃糖：那就行。\n你：只是下次不必拿尺子。\n琉璃糖把尺子放回去，又把盘子推过来：趁还没凉。"),
         new("再来一次切磋？","琉璃糖：再来一次。这次我看清了。\n你：你刚才输了。\n琉璃糖：嗯。你转身那一下，比我快。我回去练过，再来。","输了也肯承认？","琉璃糖：输了就是输了。\n她把剑收好。\n琉璃糖：你的本事我服。但下一次，还要认真打。别因为赢过我就留手。"),
         new("玲珑说你应该“开窍”。","琉璃糖：开哪里的窍？\n你：她是在逗你，不是让你找一处孔。\n琉璃糖认真想了一会儿：那她为什么不直接说？","因为她想看你这样认真想。","琉璃糖：……知道了。\n稍后她忽然抬头。\n琉璃糖：她每次逗我，都先偷看别人笑没笑。其实她比我着急吧？"),
         new("有强敌的时候，还顾得上队伍吗？","琉璃糖：先看该打谁。有人要救，就先开路。\n你：不会想追上去再打一场？\n琉璃糖：会。可同伴不能站在原地，等我打够了再走。","这不像平时被玩笑难住的你。","琉璃糖：剑从哪里来，人往哪里走，看得见。\n她皱起眉。\n琉璃糖：你们说的话，有时明明不是那个意思，还偏要那么说。这个更难。"),
         new("甘露怎么不让你练剑？","琉璃糖：伤口已经不疼了。\n你：她说还不能练。\n琉璃糖：我知道。我只是去看看。\n通讯那边传来甘露的声音：“练习剑也已经收起来啦。”","那今天做点别的？","琉璃糖：……好。\n你：可以陪大家吃饭，聊聊天。\n琉璃糖：我把恢复当成训练，可以吗？按时吃饭，按时休息。等她说可以，再拿剑。"),
         new("买东西时会讲价吗？","琉璃糖：会问多少钱。\n你：然后呢？\n琉璃糖：付钱。\n你：你没有试着少出一点？\n琉璃糖：他牌子上写了那个数。","下次让玲珑陪你去？","琉璃糖：她说过可以。条件是回来要听她讲完整个经过，不许半路去练剑。\n琉璃糖：……要是能让大家少花一点钱，也行。")],
        [new("今天准备捉弄谁？","玲珑糖：诶——先告诉你，我不就少一个人可以逗了吗？\n你：你这么说，我更会小心。\n玲珑糖：那你看见我把杯子放在桌边，就别一脸“早就知道”的样子嘛！","杯子底下是空的？","玲珑糖：……你怎么连这个都猜到了。\n你：千机昨天提醒过。\n玲珑糖：她居然提前通风报信！好，这回算你们赢。帮我把杯子收好，别真有人被绊着。"),
         new("千机也会配合你的玩笑？","玲珑糖：我只是问她，能不能装作被吓一跳。她很认真地点头，然后等我说开始。\n你：这不是挺好吗？\n玲珑糖：太认真了！轮到我反倒不知道该怎么吓她！","所以最后谁先笑了？","玲珑糖：我啦，我啦。\n她把声音压低。\n玲珑糖：不过她愿意停下工作陪我一会儿，我还挺高兴的。这句可不许拿去逗她。"),
         new("你其实很会照顾气氛。","玲珑糖：那当然，我可不是只会胡闹。\n你：刚才那位同伴不高兴，你就没再逗她。\n玲珑糖：人家真难过，继续闹就不好玩了。我说自己有点饿，叫她陪我坐会儿。","你可以直接说想陪她。","玲珑糖：……知道啦。下次也记得叫我。\n你：叫你什么？\n玲珑糖：吃饭、散步，什么都行。别每次有事才想起来，我也可以安安静静坐一会儿的。"),
         new("如果玩笑开过头了呢？","玲珑糖：先道歉。别等对方还得笑着说“没关系”。\n你：你也遇到过？\n玲珑糖把手指绕在发梢上：遇到过。所以才知道，那种时候不能再抢最后一句。","然后要怎么补救？","玲珑糖：问清楚，再做。\n玲珑糖：我会说对不起，也会把弄乱的东西收好。可不能拿一盒点心塞过去，就当自己已经哄好了。"),
         new("不怕别人觉得你只会捣乱？","玲珑糖：谁说的？我可会很多……\n她说到一半停了下来。\n玲珑糖：有时会怕。越想证明自己，越容易急。","那这次就直接叫我们帮忙。","玲珑糖：你都这么说了，我下次真叫你，可别躲。\n你：不会。\n玲珑糖：……好。这次帮帮我。那份口味会的名单，我一个人写得有点乱。"),
         new("真遇到危险，你还会开玩笑吗？","玲珑糖：看什么时候。让对面分神，可以；把自己人也耽误了，不行。\n你：你看起来总是很轻松。\n玲珑糖：总板着脸，大家就会知道我紧张呀。不过该听命令的时候，我听得见。","我们可以放心把机会交给你？","玲珑糖：可以。\n她没有拖长尾音。\n玲珑糖：看见我给的信号，就带人走。我会跟上，不会为了多赢一句嘴留下。")]];
    public static IEnumerable<int> Today(int role, int day) =>
        new[] { 0, 1, 3 }.Select(i => (day + role + i) % Topics[role].Length);
